CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS branches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, name text NOT NULL, code text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,code));
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, branch_id uuid REFERENCES branches ON DELETE SET NULL, email text NOT NULL, password_hash text NOT NULL, display_name text NOT NULL, role text NOT NULL CHECK(role IN ('owner','manager','cashier','kitchen','inventory','accountant','delivery')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,email));
CREATE TABLE IF NOT EXISTS categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, name text NOT NULL, UNIQUE(organization_id,name));
CREATE TABLE IF NOT EXISTS products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, category_id uuid REFERENCES categories ON DELETE SET NULL, sku text NOT NULL, name text NOT NULL, description text NOT NULL DEFAULT '', price numeric(12,2) NOT NULL CHECK(price>=0), image_url text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,sku));
CREATE TABLE IF NOT EXISTS ingredients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, branch_id uuid NOT NULL REFERENCES branches ON DELETE CASCADE, sku text NOT NULL, name text NOT NULL, category text NOT NULL DEFAULT '', unit text NOT NULL, stock numeric(14,3) NOT NULL DEFAULT 0 CHECK(stock>=0), track_stock boolean NOT NULL DEFAULT false, reorder_level numeric(14,3) NOT NULL DEFAULT 0 CHECK(reorder_level>=0), unit_cost numeric(12,4) NOT NULL DEFAULT 0 CHECK(unit_cost>=0), supplier_id uuid, expires_on date, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(branch_id,sku));
ALTER TABLE ingredients ADD COLUMN IF NOT EXISTS track_stock boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS recipes (product_id uuid NOT NULL REFERENCES products ON DELETE CASCADE, ingredient_id uuid NOT NULL REFERENCES ingredients ON DELETE RESTRICT, quantity numeric(14,3) NOT NULL CHECK(quantity>0), PRIMARY KEY(product_id,ingredient_id));
CREATE TABLE IF NOT EXISTS customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, name text NOT NULL, phone text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', loyalty_points integer NOT NULL DEFAULT 0 CHECK(loyalty_points>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS suppliers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, name text NOT NULL, phone text NOT NULL DEFAULT '', category text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, branch_id uuid NOT NULL REFERENCES branches ON DELETE RESTRICT, customer_id uuid REFERENCES customers ON DELETE SET NULL, order_number bigint NOT NULL, order_type text NOT NULL CHECK(order_type IN ('Dine-in','Takeaway','Pickup','Home Delivery')), status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Accepted','Preparing','Ready','Completed','Cancelled')), subtotal numeric(12,2) NOT NULL CHECK(subtotal>=0), tax numeric(12,2) NOT NULL DEFAULT 0 CHECK(tax>=0), discount numeric(12,2) NOT NULL DEFAULT 0 CHECK(discount>=0), total numeric(12,2) NOT NULL CHECK(total>=0), notes text NOT NULL DEFAULT '', created_by uuid REFERENCES users ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(branch_id,order_number));
CREATE TABLE IF NOT EXISTS order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders ON DELETE CASCADE, product_id uuid REFERENCES products ON DELETE SET NULL, product_name text NOT NULL, quantity integer NOT NULL CHECK(quantity>0), unit_price numeric(12,2) NOT NULL CHECK(unit_price>=0), line_total numeric(12,2) NOT NULL CHECK(line_total>=0));
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, branch_id uuid NOT NULL REFERENCES branches ON DELETE RESTRICT, order_id uuid REFERENCES orders ON DELETE RESTRICT, customer_id uuid REFERENCES customers ON DELETE RESTRICT, supplier_id uuid REFERENCES suppliers ON DELETE RESTRICT, amount numeric(12,2) NOT NULL CHECK(amount>0), method text NOT NULL CHECK(method IN ('Cash','Mada')), direction text NOT NULL CHECK(direction IN ('in','out')), note text NOT NULL DEFAULT '', created_by uuid REFERENCES users ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(order_id IS NOT NULL OR customer_id IS NOT NULL OR supplier_id IS NOT NULL));
CREATE TABLE IF NOT EXISTS purchases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, branch_id uuid NOT NULL REFERENCES branches ON DELETE RESTRICT, supplier_id uuid NOT NULL REFERENCES suppliers ON DELETE RESTRICT, invoice_number text NOT NULL, total numeric(12,2) NOT NULL CHECK(total>=0), paid numeric(12,2) NOT NULL DEFAULT 0 CHECK(paid>=0 AND paid<=total), status text NOT NULL DEFAULT 'received' CHECK(status IN ('received','cancelled')), created_by uuid REFERENCES users ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,invoice_number));
CREATE TABLE IF NOT EXISTS purchase_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), purchase_id uuid NOT NULL REFERENCES purchases ON DELETE CASCADE, ingredient_id uuid NOT NULL REFERENCES ingredients ON DELETE RESTRICT, quantity numeric(14,3) NOT NULL CHECK(quantity>0), unit_cost numeric(12,4) NOT NULL CHECK(unit_cost>=0), line_total numeric(12,2) NOT NULL CHECK(line_total>=0));
CREATE TABLE IF NOT EXISTS stock_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), branch_id uuid NOT NULL REFERENCES branches ON DELETE CASCADE, ingredient_id uuid NOT NULL REFERENCES ingredients ON DELETE RESTRICT, movement_type text NOT NULL CHECK(movement_type IN ('sale','purchase','adjustment','waste')), quantity_delta numeric(14,3) NOT NULL CHECK(quantity_delta<>0), reference_id uuid, note text NOT NULL DEFAULT '', created_by uuid REFERENCES users ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, branch_id uuid REFERENCES branches ON DELETE SET NULL, user_id uuid REFERENCES users ON DELETE SET NULL, action text NOT NULL, entity_type text NOT NULL, entity_id uuid, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS orders_branch_created_idx ON orders(branch_id,created_at DESC);
CREATE INDEX IF NOT EXISTS payments_branch_created_idx ON payments(branch_id,created_at DESC);
CREATE INDEX IF NOT EXISTS payments_customer_idx ON payments(customer_id,created_at DESC);
CREATE INDEX IF NOT EXISTS purchases_supplier_idx ON purchases(supplier_id,created_at DESC);
CREATE INDEX IF NOT EXISTS ingredients_branch_reorder_idx ON ingredients(branch_id,stock,reorder_level);
CREATE INDEX IF NOT EXISTS audit_org_created_idx ON audit_logs(organization_id,created_at DESC);
